expected.fmt:
import expect_equal from "@std/test/test.ms"

fn difference(values: List[Int]) Int:
	[first, second] := values
	return first - second

test "list binding":
	try expect_equal(difference([9, 4]), 5)

	{value: label} := Label("ready")
	try expect_equal(label, "ready")

type Label:
	value: String
